<script setup lang="ts">
import { computed, ref } from 'vue'
import { NModal, NCard, NForm, NFormItem, NSelect, NInput, NButton, NDatePicker, NAlert, useMessage } from 'naive-ui'
import { Upload } from 'lucide-vue-next'
import { api, errorText, groupOptions, type Group, type Platform, type Job } from '../api'
const props=defineProps<{show:boolean;kind:'accounts'|'links';groups?:Group[];platforms?:Platform[];accountId?:string;accountLabel?:string}>()
const emit=defineEmits<{ 'update:show':[boolean]; submitted:[] }>()
const text=ref(''),files=ref<{name:string;text:string}[]>([]),group=ref(''),platform=ref(''),expires=ref<number|null>(null),busy=ref(false)
const msg=useMessage(), title=computed(()=>props.kind==='accounts'?'批量导入邮箱':'导入并生成链接')
async function choose(e:Event){const list=(e.target as HTMLInputElement).files;if(!list)return;if(list.length>20){msg.warning('每次最多 20 个 TXT 文件');return};if(Array.from(list).reduce((n,f)=>n+f.size,0)>24*1024*1024){msg.warning('文件总大小不能超过 24 MiB');return};files.value=await Promise.all(Array.from(list).map(async f=>({name:f.name,text:await f.text()})))}
async function submit(){if(!text.value.trim()&&!files.value.length){msg.warning('请粘贴内容或选择文件');return};busy.value=true;try{const job=await api<Job>('admin/import','POST',{kind:props.kind,text:text.value,files:files.value,group_id:group.value||'',platform_id:platform.value||'',account_id:props.accountId||'',expires_at:expires.value?new Date(expires.value).toISOString():''});window.dispatchEvent(new CustomEvent('jobs-changed',{detail:job}));msg.success('导入已提交，将自动提示处理结果');text.value='';files.value=[];emit('update:show',false);emit('submitted')}catch(e){msg.error(errorText(e))}finally{busy.value=false}}
</script>
<template><NModal :show="show" :mask-closable="!busy" @update:show="v=>emit('update:show',v)"><NCard class="form-modal" :title="title" closable @close="emit('update:show',false)"><NForm label-placement="top" @submit.prevent="submit"><NAlert :show-icon="false" type="info"><template v-if="kind==='accounts'">Outlook：邮箱----密码----Client ID----Refresh Token<br>iCloud：邮箱----应用专用密码<br>MX：postmaster@域名----MX----30（保留天数，0 为永久）<br>重复邮箱将更新凭据。</template><template v-else>绑定 {{ accountLabel || '文件首行指定的主邮箱' }}。每行一个子邮箱地址。没有指定主邮箱时，每个文件首行填主邮箱，后续填子邮箱。重复地址保留原链接和规则。</template></NAlert><NFormItem label="导入内容"><NInput v-model:value="text" type="textarea" :rows="7" placeholder="在这里粘贴，每行一条" /></NFormItem><label class="file-picker"><Upload :size="18" />选择 TXT 文件（最多 20 个）<input type="file" accept=".txt,text/plain" multiple @change="choose"></label><small v-if="files.length" class="muted">已选：{{ files.map(f=>f.name).join('、') }}。文件和文本同时存在时优先使用文件。</small><NFormItem v-if="groups?.length" label="分组"><NSelect v-model:value="group" clearable :options="groupOptions(groups)" placeholder="不分组" /></NFormItem><template v-if="kind==='links'"><NFormItem label="平台规则"><NSelect v-model:value="platform" clearable :options="platforms?.map(p=>({label:p.name,value:p.id}))||[]" placeholder="全部平台" /></NFormItem><NFormItem label="有效期"><NDatePicker v-model:value="expires" type="datetime" clearable placeholder="长期有效" /></NFormItem></template><div class="form-actions"><NButton :disabled="busy" @click="emit('update:show',false)">取消</NButton><NButton attr-type="submit" type="primary" :loading="busy">开始导入</NButton></div></NForm></NCard></NModal></template>
